// src/utils/gitInlined.ts
const makeAPI = (data) => {
	const trackedDocsFiles = new Map(data.map(([file, timestamp]) => [file.normalize("NFC"), timestamp]));
	return { getNewestCommitDate: (file) => {
		const timestamp = trackedDocsFiles.get(file.normalize("NFC"));
		if (!timestamp) throw new Error(`Failed to retrieve the git history for file "${file}"`);
		return new Date(timestamp);
	} };
};
export { makeAPI };
